import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Насыщенность и вибранс делают цвета сильнее, но делают это по-разному. Один усиливает каждый цвет одинаково, а другой усиливает только те цвета, которым это нужно.</p>\n<p>Разница важна для естественных фото. Повышение насыщенности может сделать кожу оранжевой, а траву неоновой, а повышение вибранса защищает цвета, которые и так сильны.</p>\n<p>В этой статье мы сравним два регулятора напрямую: как они работают, как обращаются с тонами кожи, когда использовать каждый из них и как сочетать их для естественного, яркого цвета. Сравнить насыщенность и вибранс на своём фото поможет <a href=\"/ru/izmenit-nasyshchennost-izobrazheniya/\">Редактор насыщенности изображения</a> — попробуйте оба регулятора и выберите тот, что подходит снимку.</p>\n<p>Разница между насыщенностью и вибрансом кажется тонкой, пока не попробуешь оба на одном портрете. После этого сравнения вы будете точно знать, какой регулятор выбрать, и перестанете получать оранжевую кожу там, где хотели просто яркое фото.</p>\n<h2 id=\"what-each-does\">Что делает каждый регулятор</h2>\n<p>Насыщенность усиливает все цвета одинаково. Каждый оттенок на изображении становится сильнее на одинаковую величину, был ли он едва заметен или уже ярок.</p>\n<p>Вибранс сильнее усиливает приглушённые цвета и слабее — яркие. Он поднимает тусклые тона, а уже сильные цвета оставляет почти нетронутыми.</p>\n<p>В результате насыщенность может переборщить с цветами, которые и так были сильными, а вибранс поднимает слабые, не трогая сильные.</p>\n<p>Думайте о насыщенности как о ручке громкости, которая прибавляет звук каждому цвету, а о вибрансе — как об умной ручке, которая прибавляет только тихим.</p>\n<h2 id=\"how-saturation-works\">Как работает насыщенность</h2>\n<p>Насыщенность отодвигает каждый цвет от серого на одинаковую величину. Тусклый синий и яркий красный получают одинаковое повышение, поэтому красный может быстро стать слишком сильным.</p>\n<p>При плюс 100 процентах каждый цвет максимально силён. При минус 100 процентах все цвета исчезают, и изображение становится чёрно-белым.</p>\n<p>Насыщенность проста и предсказуема, поэтому её предлагают большинство редакторов. Вы точно знаете, что она сделает: сделает всё более красочным, равномерно.</p>\n<p>Слабость — в этом равномерном повышении. Фото, в котором смешаны тусклые и яркие цвета, нуждается в разной обработке для каждого, а насыщенность не может их различить.</p>\n<p>Именно поэтому насыщенность — инструмент для простых случаев: один объект, один свет, ровная сцена. Как только в кадре появляются и люди, и яркое небо, и тусклая земля, равномерный подъём начинает работать против вас.</p>\n<h2 id=\"how-vibrance-works\">Как работает вибранс</h2>\n<p>Вибранс сначала нацеливается на приглушённые цвета. Он смотрит на каждый пиксель, находит слабые цвета и усиливает их сильнее, чем те, что уже ярки.</p>\n<p>Тона кожи получают особую защиту при вибрансе. Регулятор распознаёт оранжево-красный диапазон человеческой кожи и усиливает его меньше, поэтому лица остаются естественными.</p>\n<p>В результате фото кажется более ярким, не выглядя искусственным. Тусклые области набирают цвет, а яркие остаются там, где были.</p>\n<p>Вибранс — более умный регулятор для естественной фотографии. Он делает именно то, чего большинство людей на самом деле хочет: сделать фото красочнее, не делая его ненастоящим.</p>\n<h2 id=\"key-differences\">Главные различия рядом</h2>\n<p>Насыщенность обращается со всеми цветами одинаково, а вибранс — по-разному. Это единственное различие объясняет почти всё в том, как ведут себя два регулятора.</p>\n<p>Насыщенность может выбить цвета, которые и так были сильными. Яркий красный цветок, усиленный насыщенностью, может потерять детали и стать плоским красным пятном, а вибранс оставляет его в покое.</p>\n<p>Вибранс защищает тона кожи. Портрет, усиленный вибрансом, сохраняет естественную кожу, а тот же портрет, усиленный насыщенностью, может стать оранжевым.</p>\n<p>Для фото, которое равномерно тусклое, насыщенность подходит. Для фото со смесью тусклых и ярких областей вибранс даёт более естественный результат.</p>\n<p>Проверьте это на одном и том же снимке, если ваш редактор предлагает оба регулятора: поднимите насыщенность на 30 процентов, сбросьте, затем поднимите вибранс на столько же. Разница в коже и ярких цветах будет заметна с первого взгляда.</p>\n<h2 id=\"skin-tones\">Тона кожи: здесь выигрывает вибранс</h2>\n<p>Кожа — самое сложное для правильной окраски, и именно здесь вибранс зарабатывает свою репутацию. Повышение насыщенности делает кожу оранжевой, а повышение вибранса оставляет её естественной.</p>\n<p>Причина в том, что вибранс распознаёт диапазон тонов кожи и усиливает его меньше. Лицо сохраняет естественное тепло, а цвета фона набирают яркость.</p>\n<p>Для портретов вибранс почти всегда лучше. Он делает фото красочнее, не меняя человека, а это именно то, что нужно портрету.</p>\n<p>Когда редактор предлагает только насыщенность, используйте небольшое повышение на 10–15 процентов для портретов. Такой предел сохраняет кожу естественной, а остальная часть фото набирает цвет.</p>\n<h2 id=\"landscapes\">Пейзажи: работают оба регулятора</h2>\n<p>В пейзажах мало тонов кожи, поэтому оба регулятора работают хорошо. Повышение насыщенности на 20–30 процентов делает зелень богаче, а небо — глубже.</p>\n<p>Вибранс всё же безопаснее для пейзажа со смешанными цветами. Сцене с ярким закатом и тусклым передним планом нужно поднять передний план, не выбивая закат.</p>\n<p>Для равномерно тусклого пейзажа, например в пасмурный день, насыщенность подходит. Каждому цвету нужен одинаковый подъём, и равномерное повышение хорошо справляется с задачей.</p>\n<p>Следите за листвой при любом регуляторе. Трава и листья первыми становятся неоновыми, а пейзаж со светящимися зелёными полями выглядит искусственно, какой бы регулятор вы ни использовали.</p>\n<p>Зелёный цвет — самый коварный: глаз замечает его неестественность быстрее, чем любого другого. Если сомневаетесь в пейзаже, сначала проверьте траву и листву, а уже потом небо и остальные цвета.</p>\n<h2 id=\"when-to-use-saturation\">Когда использовать насыщенность</h2>\n<p>Используйте насыщенность, когда всё фото равномерно тусклое. Пасмурный пейзаж, выцветший скан или плоский снимок в помещении — всем им нужен равномерный подъём каждого цвета.</p>\n<p>Насыщенность — также правильный выбор для осознанного стилизованного вида. Плакату или графике, которым нужны смелые, равномерные цвета, равномерное повышение идёт на пользу.</p>\n<p>Используйте насыщенность и для приглушения, и для усиления. Пресет «Приглушённый» на минус 40 процентов равномерно смягчает каждый цвет, что подходит спокойному, элегантному виду.</p>\n<p>Для перевода в чёрно-белый насыщенность — единственный регулятор, который вам нужен. Установка её на минус 100 процентов убирает весь цвет за один шаг.</p>\n<h2 id=\"when-to-use-vibrance\">Когда использовать вибранс</h2>\n<p>Используйте вибранс, когда на фото есть люди. Защита тонов кожи сохраняет лица естественными, а остальная часть изображения набирает цвет — это самый сложный баланс.</p>\n<p>Используйте вибранс, когда на фото смешанные цвета. Сцене с ярким закатом и тусклым передним планом нужно поднять передний план, не выбивая закат.</p>\n<p>Используйте вибранс для естественной фотографии в целом. Это регулятор, который ближе всего соответствует тому, что люди имеют в виду, когда говорят «сделайте цвета ярче, но чтобы не выглядело ненастоящим».</p>\n<p>Когда редактор предлагает только насыщенность, имитируйте вибранс небольшим повышением и проверкой кожи и ярких областей после каждого шага.</p>\n<p>Приём простой: поднимите насыщенность на 10 процентов, проверьте лицо, поднимите ещё на 5, снова проверьте. Как только кожа начинает теплеть сверх меры — остановитесь, даже если фону хотелось бы ещё цвета.</p>\n<h2 id=\"combining-both\">Сочетание насыщенности и вибранса</h2>\n<p>Когда редактор предлагает оба регулятора, используйте сначала вибранс, а затем насыщенность. Вибранс поднимает тусклые цвета, а небольшое повышение насыщенности затем добавляет общую насыщенность.</p>\n<p>Начните с умеренного повышения вибранса, затем добавьте 5–10 процентов насыщенности. Такое сочетание даёт яркий цвет без оранжевой кожи и неоновой травы, которые может вызвать одна насыщенность.</p>\n<p>Проверяйте кожу и яркие области после каждого шага. Два регулятора взаимодействуют, и сочетание, которое хорошо выглядит на одном уровне, на следующем может переборщить.</p>\n<p>Для фото, которому нужен лишь небольшой подъём, одного вибранса хватает. Добавление насыщенности поверх повышения вибранса может довести цвета за пределы естественного.</p>\n<h2 id=\"over-saturation-signs\">Признаки того, что вы зашли слишком далеко</h2>\n<p>Неоновая трава — самый явный признак чрезмерной насыщенности. Зелёная листва, которая светится электрически зелёным, доведена за пределы естественного, и фото выглядит искусственно.</p>\n<p>Оранжевая кожа — второй признак. Лицо, которое становится оранжевым, красным или жёлтым, получило слишком много насыщенности, и портрету нужно уменьшить ползунок.</p>\n<p>Выбитые красные — третий признак. Яркий красный цветок или красная рубашка, которые теряют детали и становятся плоским красным пятном, были усилены за пределы, где детали выживают.</p>\n<p>Нарисованное небо — четвёртый признак. Синее небо, которое выглядит как сплошной блок цвета без градиента и деталей облаков, было чрезмерно насыщено.</p>\n<p>Заведите привычку проверять эти четыре признака по списку после каждой правки: трава, кожа, красные цвета, небо. Если хотя бы один из них вызывает сомнения, уменьшите ползунок на 5 процентов и проверьте снова.</p>\n<h2 id=\"natural-colour-editing\">Естественная цветокоррекция: философия</h2>\n<p>Естественная цветокоррекция означает, что фото выглядит так, как ощущалась сцена, а не как карикатура на неё. Цвета должны быть яркими, но при этом принадлежать реальному миру.</p>\n<p>Начните с небольших сдвигов. Повышения на 10–20 процентов обычно хватает, а большие сдвиги быстро переходят границу от яркого к искусственному.</p>\n<p>Сверяйте фото со своей памятью о сцене. Если трава в реальной жизни не была неоново-зелёной, она не должна быть неоново-зелёной и на фото.</p>\n<p>Сравните отредактированное фото с оригиналом. Правка должна казаться лучшей версией того же фото, а не совсем другим снимком.</p>\n<h2 id=\"muted-looks\">Приглушённые виды: когда меньше цвета — значит больше</h2>\n<p>Приглушённый цвет — это творческий выбор, а не неудача. Фото с мягкими, тихими цветами кажется спокойным и элегантным, что подходит свадьбам, портретам и художественной фотографии.</p>\n<p>Используйте пресет «Приглушённый» на минус 40 процентов насыщенности для бережного обесцвечивания. Цвета остаются видимыми, но мягкими, и фото приобретает утончённый, сдержанный вид.</p>\n<p>Приглушение также помогает, когда цвета конфликтуют. Фото с ярким красным объектом рядом с ярким зелёным может казаться хаотичным, а приглушение обоих приносит гармонию.</p>\n<p>Для полностью обесцвеченного вида используйте «Чёрно-белый» на минус 100 процентов. Изображение становится чёрно-белым, что подходит драматичным сценам и вневременным портретам.</p>\n<p>Приглушённый вид хорошо работает и для ленты в соцсетях: когда все фото в одной спокойной палитре, профиль выглядит как продуманный журнал, а не как случайный набор снимков из разных мест.</p>\n<h2 id=\"black-and-white\">Чёрно-белый: предельное обесцвечивание</h2>\n<p>«Чёрно-белый» на минус 100 процентов убирает весь цвет. Фото становится чёрно-белым, и только яркость и контраст остаются нести изображение.</p>\n<p>Чёрно-белый подходит драматичным сценам, архитектуре и уличной фотографии, где форма и свет важнее цвета. Он также подходит портретам с сильными выражениями.</p>\n<p>После перевода проверьте контраст. Чёрно-белому фото часто нужно небольшое повышение контраста, потому что цвет нёс часть глубины, которой теперь нет.</p>\n<p>Для чёрно-белого пейзажа контраст — ваш главный инструмент. Горы, небо и передний план приобретают чёткость благодаря ясному тональному разбросу.</p>\n<h2 id=\"product-photos\">Фото товаров: точность важнее яркости</h2>\n<p>Фото товаров нуждаются в точном цвете, потому что покупатель ожидает, что товар совпадёт с фото. Повышение, которое меняет цвет товара, — это проблема, а не улучшение.</p>\n<p>Используйте вибранс для товаров, когда он у вас есть, ведь он защищает сильные фирменные цвета, поднимая тусклые. Одна насыщенность может сдвинуть цвет товара.</p>\n<p>Используйте небольшое повышение на 5–15 процентов для товаров и сверяйте цвет с реальным предметом. Фото должно совпадать с тем, что получит покупатель.</p>\n<p>Сохраняйте цвет единым для всего каталога. Магазин с совпадающими уровнями цвета выглядит аккуратно и вызывает доверие, а смешанные уровни — небрежно.</p>\n<h2 id=\"common-mistakes\">Частые ошибки с регуляторами цвета</h2>\n<p>Самая частая ошибка — использовать насыщенность там, где лучше подошёл бы вибранс. Портрет, усиленный насыщенностью, становится оранжевым, а тот же портрет, усиленный вибрансом, остаётся естественным.</p>\n<p>Ещё одна ошибка — усиливать фото, которое и так яркое. Красочный закат или яркий цветок нуждаются в небольшом повышении или вовсе без него, а добавление ещё большего только делает их кричащими.</p>\n<p>Многие забывают проверять кожу. Повышение для пейзажа, которое хорошо выглядит на природе, может сделать людей на фото оранжевыми, поэтому всегда проверяйте лица.</p>\n<p>И наконец, не настраивайте один и тот же JPG снова и снова. Каждое сохранение добавляет повреждения, поэтому для другого уровня цвета всегда возвращайтесь к исходному файлу.</p>\n<h2 id=\"cheat-sheet\">Выбор регулятора: быстрая шпаргалка</h2>\n<p>Используйте насыщенность, когда всё фото равномерно тусклое, когда нужен смелый стилизованный вид или когда нужно приглушить либо полностью убрать цвет.</p>\n<p>Используйте вибранс, когда на фото есть люди, когда в нём смешаны тусклые и яркие области или когда нужен естественный цвет, который не выглядит отредактированным.</p>\n<p>Используйте оба, когда фото нуждается в сильном подъёме: сначала вибранс для тусклых цветов, затем небольшое повышение насыщенности для общей яркости.</p>\n<p>Не используйте ни один, когда фото уже яркое. Красочной сцене нужно небольшое повышение или вовсе без него, а добавление ещё большего только делает её кричащей.</p>\n<p>Если запомнить только одно правило из этой статьи, пусть это будет оно: сначала спросите себя, тусклое ли фото на самом деле. Половина неудачных правок случается от того, что насыщенность добавляют снимку, которому она вовсе не нужна.</p>\n<h2 id=\"vibrance-travel-photos\">Вибранс и насыщенность для фото из путешествий</h2>\n<p>Фото из путешествий смешивают людей, пейзажи, еду и архитектуру в одном наборе, поэтому им нужен регулятор, который справляется с разнообразием. Вибранс обычно лучше, ведь он защищает кожу и сильные цвета, поднимая тусклые.</p>\n<p>Для набора из путешествия используйте один подход для каждого фото: умеренное повышение вибранса, затем небольшое повышение насыщенности, только если цвета всё ещё кажутся тусклыми. Единообразие сохраняет поездку ощущением одного путешествия.</p>\n<p>Проверяйте людей на каждом фото из путешествия после усиления. Повышение для пейзажа, которое хорошо выглядит на природе, может сделать путешественников оранжевыми, поэтому всегда проверяйте лица.</p>\n<p>Для альбома из путешествия сохраняйте цвет естественным. Поездка, запомнившаяся в кричащих, чрезмерно насыщенных цветах, кажется менее реальной, чем в ярких, но правдоподобных тонах.</p>\n<p>Практические шаги смотрите в статье <a href=\"/ru/blog/kak-nastroit-nasyshchennost-izobrazheniya/\">Как настроить насыщенность изображения</a>, а полный обзор — в статье <a href=\"/ru/blog/redaktor-nasyshchennosti-izobrazheniya-polnoe-rukovodstvo/\">Редактор насыщенности изображения: полное руководство</a>. Чтобы добавить единый вид всем фото, попробуйте <a href=\"/ru/filtry-dlya-izobrazhenii/\">инструмент фильтров для изображений</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"В чём разница между насыщенностью и вибрансом?","answer":"Насыщенность усиливает все цвета одинаково, а вибранс сильнее усиливает приглушённые цвета и слабее — яркие. Вибранс также защищает тона кожи, поэтому лица остаются естественными. Насыщенность проще и подходит равномерно тусклым фото, а вибранс даёт более естественный результат на смешанных сценах."},{"question":"Что лучше для портретов: насыщенность или вибранс?","answer":"Вибранс, потому что он защищает тона кожи, поднимая другие цвета. Повышение насыщенности может сделать кожу оранжевой, а вибранс сохраняет лица естественными. Когда доступна только насыщенность, используйте небольшое повышение на 10–15 процентов для портретов."},{"question":"Можно ли использовать насыщенность и вибранс на одном фото?","answer":"Да, когда редактор предлагает оба. Сначала используйте вибранс, чтобы поднять тусклые цвета, затем добавьте небольшое повышение насыщенности на 5–10 процентов для общей яркости. Проверяйте кожу и яркие области после каждого шага, ведь два регулятора взаимодействуют."},{"question":"Почему пейзаж выглядит ненастоящим после усиления цвета?","answer":"Повышение было слишком сильным: трава становится неоново-зелёной, а небо — плоскими синими блоками. Уменьшите ползунок, пока цвета не станут яркими, но всё ещё реальными. Для пейзажей обычно достаточно повышения на 20–30 процентов."},{"question":"Меняет ли вибранс яркость фото?","answer":"Нет: вибранс нацеливается на интенсивность цвета, а не на яркость. Он поднимает приглушённые цвета, не делая изображение светлее или темнее. Так легче оценивать изменение цвета само по себе, без сдвига яркости под ним."},{"question":"Насыщенность или вибранс использовать для фото товаров?","answer":"Вибранс, когда он у вас есть, ведь он защищает сильные фирменные цвета, поднимая тусклые. При одной насыщенности используйте небольшое повышение на 5–15 процентов и сверяйте цвет с реальным предметом, ведь точность важнее яркости."}];
